#!/usr/bin/env python3# -*- coding: utf-8 -*-"""prbe.pyImplements Manby & Miller Projection Based Embedding using the Huzinaga Projection Operator. author: Ardavan Farahvash, github.com/afarahva"""import warningsfrom functools import partialimport numpy as npfrom pyscf.pbc import scffrom pyscf.scf.smearing import (_fermi_smearing_occ, _gaussian_smearing_occ,                                 _smearing_optimize)from pyscf.scf import addons as mol_addonsfrom pyscf.lib import loggerfrom pyscf.pbc import toolsfrom pyscf.pbc.scf import addonsfrom pyscf.pbc.lib import kpts_helperfrom pyscf.pbc.lib.kpts import KPointsfrom pyscf.pbc.scf.smearing import _partition_occdef _lowdin_transform(ovlp):    """Return S^{+1/2} and S^{-1/2} for one overlap matrix."""    eigval, eigvec = np.linalg.eigh(ovlp)    safe = np.maximum(eigval, 0.0)    s_sqrt    = (eigvec * np.sqrt(safe))                          @ eigvec.conj().T    s_invsqrt = (eigvec * (1.0 / np.sqrt(np.maximum(safe, 1e-15)))) @ eigvec.conj().T    return s_sqrt, s_invsqrtdef get_mu(mf):    """Converged chemical potential of a smeared K-SCF, recomputed from its    own dense k-mesh (PySCF does not persist it)."""    f = _fermi_smearing_occ if mf.smearing_method.lower() == 'fermi' else _gaussian_smearing_occ    mo_es = np.hstack(mf.mo_energy)    nocc  = (mf.cell.tot_electrons(len(mf.kpts)) + 1) // 2   # electrons per spin (restricted)    mu, _ = _smearing_optimize(f, mo_es, nocc, mf.sigma)    return mudef band_occ(mf, mu, mo_energy_band):    """Occupancies at band k-points using a FIXED chemical potential mu."""    f = _fermi_smearing_occ if mf.smearing_method.lower() == 'fermi' else _gaussian_smearing_occ    spin = 1.0 if mf.istype('KUHF') else 2.0    return [spin * f(mu, np.asarray(ek), mf.sigma) for ek in mo_energy_band]def rdm1_BZdownfold(kmf, fine_mesh, coarse_mesh, dm=None, symmetrize=True):    """    Commensurate BZ downfolding from a fine M×M×M k-mesh to a coarse N×N×N    k-mesh (N_i | M_i required) base on REAL-SPACE Averaging     The BZ→R=0 downfolding gives the R=0 real-space density matrix block by    averaging over all k:        γ_L(R=0) = (1/Nk) Σ_k γ_L(k)     This function generalises that to a coarse k-mesh by computing the    real-space DM from the fine mesh and Fourier-transforming it at the coarse    k-points, retaining only real-space blocks within the N-supercell:         Step 1 – Löwdin:  γ_L(k)   = S(k)^{1/2} γ(k) S(k)^{1/2}   ∀ fine k        Step 2 – IFFT:    γ_L(R)   = (1/Nk) Σ_k e^{ik·R} γ_L(k)        Step 3 – Truncate:           keep R with n_i ∈ {0,…,N_i−1} only        Step 4 – FFT:     γ_L(K)   = Σ_{R∈[0,N)} e^{−iK·R} γ_L(R)        Step 5 – Symmetrise:         (γ_L + γ_L†) / 2  (Hermiticity)        Step 6 – Back-transform: γ(K) = S(K)^{-1/2} γ_L(K) S(K)^{-1/2}     Steps 2-4 are equivalent to a complex-weighted sum over ALL fine k-points:        γ_L(K) = (1/Nk) Σ_k  [Π_α Σ_{n=0}^{N_α-1} e^{i2π n(m_α/M_α - m'_α/N_α)}] γ_L(k)    The phase factors in the brackets are what a naive block-average misses.     Setting coarse_mesh = [1,1,1] recovers make_downfolded_rdm1() exactly:    the IFFT at R=0 is the k-average, and the FFT of a 1×1×1 array is    the identity.     Note on Hermiticity: the R-truncation to n_i ∈ {0,…,N-1} is asymmetric    (it includes R=+n*a but not R=-n*a).  Step 5 symmetrises the result,    which is equivalent to giving boundary lattice vectors half-weight — the    standard practice in Wannier interpolation.     Parameters    ----------    kmf         : converged PySCF KRHF / KRKS object                  (KUHF: call separately for α and β channels)    fine_mesh   : [M1, M2, M3]  — must match the mesh used for kmf.kpts    coarse_mesh : [N1, N2, N3]  — N_i must divide M_i     Returns    -------    rdm1_coarse : ndarray (Nkcoarse, Nao, Nao), real    coarse_kpts : ndarray (Nkcoarse, 3), Cartesian 1/Bohr    """    if not kmf.converged:        warnings.warn("kmf object is not marked as converged.", UserWarning)     fine_mesh   = np.asarray(fine_mesh,   dtype=int)    coarse_mesh = np.asarray(coarse_mesh, dtype=int)    M1, M2, M3  = fine_mesh    N1, N2, N3  = coarse_mesh     # ── commensurability ──────────────────────────────────────────────────────    rem = fine_mesh % coarse_mesh    if np.any(rem != 0):        bad = np.where(rem != 0)[0]        raise ValueError(            f"Incommensurate meshes at dimension(s) {bad.tolist()}: "            f"fine={fine_mesh[bad].tolist()} not divisible by "            f"coarse={coarse_mesh[bad].tolist()}."        )    p = fine_mesh // coarse_mesh    # (3,)     if dm is None:        dm_kpts   = np.asarray(kmf.make_rdm1())   # (Nkfine, Nao, Nao)            else:        dm_kpts=dm    nkfine, nao, _ = dm_kpts.shape    ovlp_kpts = np.asarray(kmf.get_ovlp())    # (Nkfine, Nao, Nao)     if nkfine != int(M1 * M2 * M3):        raise ValueError(            f"kmf has {nkfine} k-points but fine_mesh {fine_mesh.tolist()} "            f"implies {int(M1*M2*M3)}."        )     # ── Step 1: Löwdin DMs at all fine k ─────────────────────────────────────    rdm1_L_all = np.empty((nkfine, nao, nao), dtype=complex)    for i in range(nkfine):        s_sqrt, _ = _lowdin_transform(ovlp_kpts[i])        rdm1_L_all[i] = s_sqrt @ dm_kpts[i] @ s_sqrt     # Map each fine k-point to its 3D grid index (n1, n2, n3)    # Robust to any k-point ordering PySCF uses    fine_ksc = kmf.cell.get_scaled_kpts(kmf.kpts) % 1.0     # (Nkfine, 3)    fine_n   = np.round(fine_ksc * fine_mesh).astype(int) % fine_mesh     # Arrange into a 3D grid for the FFT    rdm1_L_3d = np.zeros((M1, M2, M3, nao, nao), dtype=complex)    for i in range(nkfine):        rdm1_L_3d[fine_n[i, 0], fine_n[i, 1], fine_n[i, 2]] = rdm1_L_all[i]     # ── Step 2: IFFT k → R  (numpy ifftn matches our sign convention) ─────────    # ifftn[n1,n2,n3] = (1/M) Σ_{m} e^{+i2π(m1n1/M1 + …)} X[m1,m2,m3]    # ↔  γ_L(R_n) = (1/Nk) Σ_k e^{+ik·R_n} γ_L(k)  ✓    rdm1_L_R = np.fft.ifftn(rdm1_L_3d, axes=(0, 1, 2))   # (M1,M2,M3, Nao,Nao)     # ── Step 3: Truncate to the N-supercell ───────────────────────────────────    rdm1_L_N  = rdm1_L_R[:N1, :N2, :N3, :, :]            # (N1,N2,N3, Nao,Nao)     # ── Step 4: FFT R → coarse K  ─────────────────────────────────────────────    # fftn[m'1,m'2,m'3] = Σ_n e^{−i2π(m'1n1/N1+…)} X[n1,n2,n3]    # ↔  γ_L(K_{m'}) = Σ_{R∈[0,N)} e^{−iK·R} γ_L(R)  ✓    rdm1_L_K  = np.fft.fftn(rdm1_L_N,  axes=(0, 1, 2))   # (N1,N2,N3, Nao,Nao)     # ── Step 5: Symmetrise (asymmetric R-truncation breaks Hermiticity) ───────    if symmetrize:        rdm1_L_K  = 0.5 * (rdm1_L_K + rdm1_L_K.conj().transpose(0, 1, 2, 4, 3))     # ── coarse k-points and their indices in the fine mesh ────────────────────    coarse_kpts     = kmf.cell.make_kpts(coarse_mesh.tolist())   # (Nkcoarse, 3)    nkcoarse        = len(coarse_kpts)    coarse_ksc      = kmf.cell.get_scaled_kpts(coarse_kpts) % 1.0    coarse_n        = np.round(coarse_ksc * coarse_mesh).astype(int) % coarse_mesh     # For each coarse K, find its overlap in the fine mesh    # Coarse (m'1,m'2,m'3) sits exactly at fine index (m'1*p1, m'2*p2, m'3*p3)    coarse_in_fine = np.empty(nkcoarse, dtype=int)    for j in range(nkcoarse):        expected = coarse_n[j] * p        hits = np.where(np.all(fine_n == expected, axis=1))[0]        if len(hits) != 1:            raise RuntimeError(                f"Coarse k-point {j} matched {len(hits)} fine k-points "                f"(expected 1). Check both meshes are Gamma-centered."            )        coarse_in_fine[j] = hits[0]     # ── Step 6: Back-transform to AO at each coarse K ─────────────────────────    if nkcoarse==1:        rdm1_coarse = np.empty((nkcoarse, nao, nao),dtype=np.complex128)    else:        rdm1_coarse = np.empty((nkcoarse, nao, nao),dtype=np.float64)     for j in range(nkcoarse):        m1, m2, m3 = coarse_n[j]        rdm1_L = rdm1_L_K[m1, m2, m3]                      # (Nao, Nao)         idx_K = coarse_in_fine[j]        _, s_invsqrt = _lowdin_transform(ovlp_kpts[idx_K])        rdm1_K = s_invsqrt @ rdm1_L @ s_invsqrt.conj().T   # (Nao, Nao)                if nkcoarse==1:            rdm1_coarse[j] = rdm1_K.real        else:            rdm1_coarse[j] = rdm1_K        return rdm1_coarsedef BZsubsample(kmf, fine_mesh, coarse_mesh):    """    Subsample the density matrix at finite k-points        Parameters    ----------    kmf         : converged PySCF KRHF / KRKS object                  (KUHF: call separately for α and β channels)    fine_mesh   : [M1, M2, M3]  — must match the mesh used for kmf.kpts    coarse_mesh : [N1, N2, N3]  — N_i must divide M_i     Returns    -------    rdm1_coarse : ndarray (Nkcoarse, Nao, Nao), real    coarse_kpts : ndarray (Nkcoarse, 3), Cartesian 1/Bohr    """    if not kmf.converged:        warnings.warn("kmf object is not marked as converged.", UserWarning)     fine_mesh   = np.asarray(fine_mesh,   dtype=int)    coarse_mesh = np.asarray(coarse_mesh, dtype=int)    M1, M2, M3  = fine_mesh    N1, N2, N3  = coarse_mesh     # ── commensurability ──────────────────────────────────────────────────────    rem = fine_mesh % coarse_mesh    if np.any(rem != 0):        bad = np.where(rem != 0)[0]        raise ValueError(            f"Incommensurate meshes at dimension(s) {bad.tolist()}: "            f"fine={fine_mesh[bad].tolist()} not divisible by "            f"coarse={coarse_mesh[bad].tolist()}."        )        nkfine = kmf.kpts.shape[0]    if nkfine != int(M1 * M2 * M3):        raise ValueError(            f"kmf has {nkfine} k-points but fine_mesh {fine_mesh.tolist()} "            f"implies {int(M1*M2*M3)}."        )            coarse_grid = kmf.cell.make_kpts(coarse_mesh)    fine_grid = kmf.cell.make_kpts(fine_mesh)    # ── fine matching indices and downfold ────────────────────    indx_match = [x for x in range(coarse_grid.shape[0]) if np.any(np.all(fine_grid == coarse_grid[x], axis=1))]    return indx_matchdef embed_get_occ(mf, mo_energy_kpts=None, mo_coeff_kpts=None,                  e_res=None, nkpts_tot=None):    '''Restricted k-point smearing get_occ for projection-based embedding.    Template: pyscf.pbc.scf.smearing _SmearingKSCF.get_occ (restricted branch).    The chemical potential is optimized over the embedded k-points (current    iteration) together with the frozen reservoir energies `e_res` (rest of the    BZ at the bath level), conserving the total electron number of the full    `nkpts_tot`-point mesh. Occupancies are returned for the embedded k-points.    Bind `e_res`/`nkpts_tot` with functools.partial.    '''    if (mf.sigma == 0) or (not mf.sigma) or (not mf.smearing_method):        raise RuntimeError('embed_get_occ is only meaningful with active smearing')    sigma = mf.sigma    if mf.smearing_method.lower() == 'fermi':        f_occ = mol_addons._fermi_smearing_occ    else:        f_occ = mol_addons._gaussian_smearing_occ    kpts = getattr(mf, 'kpts', None)    if isinstance(kpts, KPoints):        nkpts = kpts.nkpts        mo_energy_kpts = kpts.transform_mo_energy(mo_energy_kpts)    else:        nkpts = len(kpts)    # (1) electron count over the FULL mesh, not the embedded subset    nelectron = mf.mol.tot_electrons(nkpts_tot)    nocc = (nelectron + 1) // 2                          # restricted    mo_es  = np.hstack(mo_energy_kpts)                # embedded, this iteration    mo_all = np.concatenate([e_res, mo_es])          # (2) + frozen reservoir    if mf.mu0 is None:        mu, _ = mol_addons._smearing_optimize(f_occ, mo_all, nocc, sigma)    else:        # If mu0 is given, fix mu instead of electron number. XXX -Chong Sun        mu = mf.mu0        assert np.isscalar(mu)    mf.mu = mu    # (3) occupancies for the embedded k-points only, at the global mu    mo_occs = f_occ(mu, mo_es, sigma)    mf.entropy = mf._get_entropy(mo_es, mo_occs, mu) / nkpts_tot   # (4) per-cell norm    mo_occs *= 2    mf.entropy *= 2    fermi = mol_addons._get_fermi(mo_all, nocc)    logger.debug(mf, '    Fermi level %g  Sum mo_occ_kpts(embedded) = %s  '                 '(global nelec = %s over %d kpts)',                 fermi, mo_occs.sum(), nelectron, nkpts_tot)    logger.info(mf, '    sigma = %g  Optimized mu = %.12g  entropy = %.12g',                sigma, mu, mf.entropy)    mo_occ_kpts = _partition_occ(mo_occs, mo_energy_kpts)    tools.print_mo_energy_occ_kpts(mf, mo_energy_kpts, mo_occ_kpts, False)    if isinstance(kpts, KPoints):        mo_occ_kpts = kpts.check_mo_occ_symmetry(mo_occ_kpts)    return mo_occ_kptsclass krPRBE:    """    Periodic Restricted Projection Based Embedding (krPRBE) class.    asdfΩ    Manages embedding potentials and projectors for closed-shell RHF/RKS references.    """        def __init__(self, mf, kpts, df='gdf', xc_embed=None, sigma=None,                  smearing_method='fermi',  **kwargs):                        # embedded k-points        self.kpts_A = kpts        # bath k-points        self.kpts_B = mf.kpts        # embedded xc functional         self.xc_embed = xc_embed        # bath mf object        self.mf_B = mf        # bath total energy        self.energy_B=self.mf_B.e_tot                #        self.idxB = self.match_kpts(self.kpts_A,self.kpts_B)                # create fragment MF object            self.mf_A = scf.KRKS(self.mf_B.cell,**kwargs)        self.mf_A.xc = xc_embed                    if df=='gdf':            self.mf_A = self.mf_A.density_fit()        elif df=='rsgdf' or df=='rsdf':            self.mf_A = self.mf_A.rs_density_fit()        else:            raise NotImplementedError('Embedding not implemented for non-gaussian DF')                    self.mf_A.kpts=kpts        self.mf_A.diis_space = self.mf_B.diis_space        self.mf_A.diis_damp = self.mf_B.diis_damp        self.mf_A.max_cycle = self.mf_B.max_cycle        self.mf_A.verbose = self.mf_B.verbose                # for finite-temperature calculations        if sigma is not None:            self.sigma=sigma            self.smearing_method = smearing_method            # set unconditionally (see note)            self.mf_A = addons.smearing_(self.mf_A,                                         sigma=self.sigma, method=self.smearing_method)            self._attach_get_occ(self.mf_A, self.mf_B, self.idxB)            self.muB = get_mu(self.mf_B)            self.mf_A.mu0 = self.muB                           # <-- THE FIX: pin embedded μ to the global one                def _attach_get_occ(self, mf_A, mf_B, idxB):        nkB  = len(mf_B.kpts)        keep = np.ones(nkB, bool); keep[np.asarray(idxB)] = False   # bath \ embedded        e_res = (np.hstack([np.asarray(mf_B.mo_energy[k]) for k in np.where(keep)[0]])                 if keep.any() else np.zeros(0))        mf_A.get_occ = partial(embed_get_occ, mf_A, e_res=e_res, nkpts_tot=nkB)                            def match_kpts(self, kpts_A, kpts_B):        indx_match = []        for kpt in kpts_A:            match = kpts_helper.member(kpt, kpts_B)            if match.size == 1:                indx_match.append(match[0])        return indx_match                    def kernel(self, hcore=None):        """Main execution block. Sets up the embedded Hamiltonian and runs the Huzinaga SCF loop."""                # mf object        mf_A = self.mf_A        mf_B = self.mf_B        idxB = self.idxB                # density embedded density fitted integrals        df = mf_A.with_df        df.build()                # this second MF object copies the first, but with the mf_B xc functional        mf_A_prime = mf_A.copy()                mf_A_prime.xc = mf_B.xc        mf_A_prime.with_df = df        # For each kpt in A, find its index in B (or -1 if absent).                if len(idxB) < self.kpts_A.shape[0]:            raise NotImplementedError("""Every embedded k-point must be in the         dense mesh, please rerun bath DFT using k-points you wish to embed""")                if hcore is None:            dm_b = mf_B.make_rdm1()            if len(self.kpts_A)==1 and (np.asarray(self.kpts_A[0]) < 1e-5).all():                dm_b = dm_b.real            fock_b = mf_B.get_fock(dm=dm_b)[idxB]            v_a = mf_A_prime.get_veff(dm=dm_b[idxB])            hcore = fock_b - v_a            del fock_b        self.hcore = hcore                if len(self.kpts_A)==1 and (np.asarray(self.kpts_A[0]) < 1e-5).all():            hcore=hcore.real            v_a=v_a.real                # set core matrix        mf_A.get_hcore = lambda *args: hcore                # run embedded SCF        logger.info(mf_A, 'RUNNING EMBEDDED SCF')        mf_A.kernel(dm0=dm_b[idxB])        self.energy_embed = mf_A.e_tot                self.energy_A, _ = mf_A_prime.energy_elec(dm_kpts=dm_b[idxB], h1e_kpts=hcore, vhf=v_a)        self.energy_A_in_B = self.energy_embed - mf_A.energy_nuc()        self.e_tot = self.energy_A_in_B + self.energy_B - self.energy_A        return self.e_tot, mf_A.mo_energy, mf_A.mo_coeff, mf_A.mo_occ#%%if __name__ == '__main__':        from pyscf.pbc import gto, scf, mp    import matplotlib.pyplot as plt    #── hard-coded settings ───────────────────────────────────────────────────────    # BASIS        = 'gthdzvpmoloptsr'    BASIS        = 'gthszvmoloptsr'    PSEUDO       = 'gth-pbe'    N = 3    M = 1        #%%    # ── k-mesh convergence sweep ──────────────────────────────────────────────────    # Primitive lattice vectors for an FCC crystal    a = 3.6149  # A    cell = gto.Cell()    cell.atom = [        ['Li', (0.,   0.,   0.  )],        ['Li', (a/2,  a/2,  a/2 )],    ]    cell.a = np.eye(3) * a    cell.unit='A'    cell.basis   = BASIS    cell.pseudo  = PSEUDO    cell.verbose = 4    cell.build()        kmf = scf.KRKS(cell, kpts=cell.make_kpts([M, M, M])).density_fit()    kmf.xc='pbe0'    kmf = scf.addons.smearing_(kmf,sigma= 0.000950037255711,method='fermi')    kmf.kernel()    ehybrid_M = kmf.e_tot        kmf = scf.KRKS(cell, kpts=cell.make_kpts([N, N, N])).density_fit()    kmf.xc='pbe0'    kmf = scf.addons.smearing_(kmf,sigma= 0.000950037255711,method='fermi')    kmf.kernel()    ehybrid_N = kmf.e_tot        kmf = scf.KRKS(cell, kpts=cell.make_kpts([N, N, N])).density_fit()    kmf.xc='pbe'    kmf = scf.addons.smearing_(kmf,sigma= 0.000950037255711,method='fermi')    kmf.kernel()    epure_N = kmf.e_tot    #%%    # high level calculation    prbe = krPRBE(kmf, cell.make_kpts([1, 1, 1]), xc_embed='pbe0', sigma= 0.000950037255711)    e_embed,_,_,_ = prbe.kernel()    print(e_embed,ehybrid_M,ehybrid_N,epure_N)    #%%    kpts = cell.make_kpts([N, N, N])    e_kpts=[]    for i in range(len(kpts)):        prbe = krPRBE(kmf, kpts[0:i+1], xc_embed='pbe0', sigma= 0.000950037255711)        e_embed,_,_,_ = prbe.kernel()        e_kpts.append(e_embed)    plt.plot(e_kpts-ehybrid_N)